<?php
$rootPath = '../'; require_once __DIR__ . '/../config/auth.php'; require_admin(); $users = $pdo->query('SELECT id, name, email, role, created_at FROM users ORDER BY created_at DESC')->fetchAll(); $pageTitle = 'Users'; require __DIR__ . '/../includes/header.php';
